  /* ======================================================================
   *  PARTAGE : image de l'ouverture ou du classeur, à poster sur NoelShack
   * ==================================================================== */
  const imgCache = {};
  function loadImg(src) {
    if (imgCache[src]) return imgCache[src];
    imgCache[src] = new Promise((resolve) => {
      const done = (url) => { const im = new Image(); im.onload = () => resolve(im); im.onerror = () => resolve(null); im.src = url; };
      if (src.startsWith('data:') || typeof GM_xmlhttpRequest !== 'function') return done(src);
      GM_xmlhttpRequest({ method: 'GET', url: src, responseType: 'blob',
        onload: (r) => (r.status === 200 && r.response ? done(URL.createObjectURL(r.response)) : resolve(null)), onerror: () => resolve(null) });
    });
    return imgCache[src];
  }
  function rr(ctx, x, y, w, hh, r) { ctx.beginPath(); ctx.moveTo(x + r, y); ctx.arcTo(x + w, y, x + w, y + hh, r); ctx.arcTo(x + w, y + hh, x, y + hh, r); ctx.arcTo(x, y + hh, x, y, r); ctx.arcTo(x, y, x + w, y, r); ctx.closePath(); }
  const displayPseudo = () => { const el = $('.headerAccount__pseudo'); return el ? el.textContent.trim() : 'Anonyme'; };
  function shareBg(ctx, W, H) {
    const g = ctx.createRadialGradient(W / 2, H * 0.38, 40, W / 2, H * 0.45, Math.max(W, H) * 0.75);
    g.addColorStop(0, '#2f2056'); g.addColorStop(0.55, '#17122a'); g.addColorStop(1, '#0c0b12');
    ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    ctx.fillStyle = 'rgba(255,255,255,.035)';
    for (let i = 0; i < 70; i++) { ctx.beginPath(); ctx.arc((i * 137.5) % W, (i * 89.3) % H, 1 + (i % 3), 0, Math.PI * 2); ctx.fill(); }
  }
  function drawCard(ctx, im, x, y, w, hh, { glow, holo, missing, num } = {}) {
    ctx.save();
    if (missing) {
      rr(ctx, x, y, w, hh, w * 0.05); ctx.fillStyle = 'rgba(255,255,255,.05)'; ctx.fill();
      ctx.strokeStyle = 'rgba(255,255,255,.14)'; ctx.lineWidth = 2; ctx.stroke();
      ctx.fillStyle = '#4b4862'; ctx.textAlign = 'center'; ctx.font = `800 ${Math.round(w * 0.28)}px system-ui,Segoe UI,Arial`; ctx.fillText('?', x + w / 2, y + hh / 2 + w * 0.06);
      ctx.font = `700 ${Math.round(w * 0.11)}px system-ui,Segoe UI,Arial`; ctx.fillText('N° ' + num, x + w / 2, y + hh / 2 + w * 0.24);
      ctx.restore(); return;
    }
    ctx.shadowColor = glow || 'rgba(0,0,0,.6)'; ctx.shadowBlur = glow ? 28 : 18; ctx.shadowOffsetY = glow ? 0 : 8;
    rr(ctx, x, y, w, hh, w * 0.045); ctx.fillStyle = '#111'; ctx.fill();
    ctx.shadowColor = 'transparent';
    ctx.save(); rr(ctx, x, y, w, hh, w * 0.045); ctx.clip();
    if (im) ctx.drawImage(im, x, y, w, hh);
    if (holo) {
      const lg = ctx.createLinearGradient(x, y, x + w, y + hh);
      ['rgba(255,90,190,0)', 'rgba(255,90,190,.28)', 'rgba(80,200,255,.28)', 'rgba(150,255,90,.24)', 'rgba(255,210,70,.28)', 'rgba(255,210,70,0)'].forEach((c, i) => lg.addColorStop(i / 5, c));
      ctx.globalCompositeOperation = 'color-dodge'; ctx.fillStyle = lg; ctx.fillRect(x, y, w, hh); ctx.globalCompositeOperation = 'source-over';
    }
    ctx.restore();
    if (glow) { rr(ctx, x - 1.5, y - 1.5, w + 3, hh + 3, w * 0.05); ctx.strokeStyle = glow; ctx.lineWidth = 3; ctx.stroke(); }
    ctx.restore();
  }
  function pill(ctx, text, cx, y, bg, fg, size = 18) {
    ctx.save(); ctx.font = `900 ${size}px system-ui,Segoe UI,Arial`; const w = ctx.measureText(text).width + size * 1.4, hh = size * 1.7;
    rr(ctx, cx - w / 2, y - hh / 2, w, hh, hh / 2); ctx.fillStyle = bg; ctx.fill();
    ctx.fillStyle = fg; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.fillText(text, cx, y + 1); ctx.restore();
  }
  async function renderOpeningImage(pulls) {
    const W = 1200, H = 780, cv = document.createElement('canvas'); cv.width = W; cv.height = H; const ctx = cv.getContext('2d');
    shareBg(ctx, W, H);
    ctx.fillStyle = '#fff'; ctx.textAlign = 'center'; ctx.font = '900 46px system-ui,Segoe UI,Arial'; ctx.fillText('Mon booster NNN 2026', W / 2, 78);
    ctx.fillStyle = '#b9b3d1'; ctx.font = '600 22px system-ui,Segoe UI,Arial'; ctx.fillText(`Ouvert par ${displayPseudo()} · cartes illustrées par Balade92`, W / 2, 116);
    const n = pulls.length, gap = n > 3 ? 24 : 44, cw = n > 3 ? Math.floor((W - 80 - (n - 1) * gap) / n) : 300, ch = Math.round(cw * 1336 / 961), x0 = (W - (n * cw + (n - 1) * gap)) / 2, y = n > 3 ? 230 : 180;
    const ims = await Promise.all(pulls.map((p) => loadImg(byId[p.id].img)));
    pulls.forEach((p, i) => {
      const c = byId[p.id], k = fxOf(c), x = x0 + i * (cw + gap);
      drawCard(ctx, ims[i], x, y, cw, ch, { glow: k ? FX[k].color : p.holo ? '#ffd25a' : null, holo: p.holo });
      if (k) pill(ctx, FX[k].icon + ' ' + fxLabel(k) + (p.holo ? ' BRILLANTE' : ''), x + cw / 2, y - 8, FX[k].color, '#14203a');
      else pill(ctx, p.holo ? '✨ NOUVELLE BRILLANTE' : '★ NOUVELLE', x + cw / 2, y - 8, '#ffd25a', '#3b2400');
    });
    const s = load(), owned = CARDS.filter((c) => s.cards[c.id] && s.cards[c.id].n).length;
    ctx.fillStyle = '#8f89aa'; ctx.font = '700 20px system-ui,Segoe UI,Arial'; ctx.textAlign = 'center';
    ctx.fillText(`Collection : ${owned}/${CARDS.length} cartes · topic No Nut November 2026`, W / 2, H - 34);
    return cv;
  }
  async function renderBinderImage() {
    const s = load(), cols = 8, cw = 132, ch = Math.round(cw * 1336 / 961), gap = 16, pad = 60, rows = Math.ceil(CARDS.length / cols);
    const W = pad * 2 + cols * cw + (cols - 1) * gap, top = 190, H = top + rows * ch + (rows - 1) * gap + 90;
    const cv = document.createElement('canvas'); cv.width = W; cv.height = H; const ctx = cv.getContext('2d');
    shareBg(ctx, W, H);
    const owned = CARDS.filter((c) => s.cards[c.id] && s.cards[c.id].n), exAll = CARDS.filter((c) => c.rarity === 'ex'), exOwned = exAll.filter((c) => s.cards[c.id] && s.cards[c.id].n);
    const holos = owned.filter((c) => s.cards[c.id].holo).length;
    ctx.textAlign = 'left'; ctx.fillStyle = '#fff'; ctx.font = '900 44px system-ui,Segoe UI,Arial'; ctx.fillText(`Le classeur de ${displayPseudo()}`, pad, 80);
    ctx.fillStyle = '#b9b3d1'; ctx.font = '600 22px system-ui,Segoe UI,Arial';
    ctx.fillText(`${owned.length}/${CARDS.length} cartes · ${exOwned.length}/${exAll.length} ex · ${holos} brillante${holos > 1 ? 's' : ''} · NNN 2026, cartes de Balade92`, pad, 118);
    rr(ctx, pad, 142, W - pad * 2, 14, 7); ctx.fillStyle = 'rgba(255,255,255,.08)'; ctx.fill();
    const pw = (W - pad * 2) * owned.length / CARDS.length;
    if (pw > 0) { const lg = ctx.createLinearGradient(pad, 0, pad + pw, 0); lg.addColorStop(0, '#7b3fe0'); lg.addColorStop(1, '#e04aa0'); rr(ctx, pad, 142, Math.max(14, pw), 14, 7); ctx.fillStyle = lg; ctx.fill(); }
    const list = CARDS.slice().sort((a, b) => a.num - b.num);
    const ims = await Promise.all(list.map((c) => (s.cards[c.id] && s.cards[c.id].n ? loadImg(c.img) : null)));
    list.forEach((c, i) => {
      const x = pad + (i % cols) * (cw + gap), y = top + Math.floor(i / cols) * (ch + gap), own = s.cards[c.id] && s.cards[c.id].n, k = fxOf(c);
      drawCard(ctx, ims[i], x, y, cw, ch, own ? { glow: k ? FX[k].color : null, holo: s.cards[c.id].holo } : { missing: true, num: c.num });
    });
    ctx.fillStyle = '#8f89aa'; ctx.font = '700 18px system-ui,Segoe UI,Arial'; ctx.textAlign = 'center';
    ctx.fillText('Topic No Nut November 2026 · jeuxvideo.com', W / 2, H - 34);
    return cv;
  }
  async function openShare(kind, data) {
    if (!win) return;
    sfx.tick();
    const box = h(`<div class="bb-zoom bb-share"><div class="bb-share-in"><div class="bb-muted">Création de l'image…</div></div><button class="bb-x">✕</button></div>`);
    $('.bb-win', win).appendChild(box);
    $('.bb-x', box).onclick = () => box.remove();
    box.addEventListener('mousedown', (e) => { if (e.target === box) box.remove(); });
    let cv;
    try { cv = kind === 'binder' ? await renderBinderImage() : await renderOpeningImage(data); } catch (e) { $('.bb-share-in', box).innerHTML = '<p class="bb-muted">Impossible de créer l\'image.</p>'; return; }
    const url = cv.toDataURL('image/png');
    const name = kind === 'binder' ? 'classeur-nnn-2026.png' : 'booster-nnn-2026.png';
    $('.bb-share-in', box).innerHTML = `<img class="bb-share-img" src="${url}" alt="Aperçu de l'image à partager">
      <p class="bb-muted">Copie l'image, ouvre NoelShack et colle-la (Ctrl+V), ou télécharge-la puis envoie-la sur NoelShack.</p>
      <div class="row"><button class="bb-btn gold bb-cp">Copier l'image</button><a class="bb-btn" download="${name}" href="${url}">Télécharger</a>
      <a class="bb-btn ghost" href="https://www.noelshack.com/" target="_blank" rel="noopener">Ouvrir NoelShack</a></div>`;
    $('.bb-cp', box).onclick = async (e) => {
      const b = e.currentTarget;
      try {
        const blob = await new Promise((r) => cv.toBlob(r, 'image/png'));
        await navigator.clipboard.write([new ClipboardItem({ 'image/png': blob })]);
        b.textContent = 'Image copiée'; toast('Image copiée. Colle-la sur NoelShack avec Ctrl+V.');
      } catch (err) { b.textContent = 'Copie impossible : télécharge-la'; }
    };
  }

