    if (atk.healTeam && !A.ko) { PX.team.forEach((f, i) => { if (!f.ko && !f.gone) { f.hp += atk.healTeam; f.max = Math.max(f.max, f.hp); st.ev.push({ k: 'heal', side: X, i, v: atk.healTeam }); } }); L(st, `Les vocaroos redonnent de l'énergie : +${atk.healTeam} PV à toute l'équipe.`, 'fx'); }
