    if (atk.debuff && D && !D.ko) { if (CB[D.id].immuneStatus || D.shield > 0) L(st, `${cname(D.id)} est immunisé.`, 'fx'); else { D.debuff += atk.debuff; L(st, `${cname(D.id)} est déstabilisé (−${atk.debuff} atk).`, 'fx'); } }
