    if (atk.gainHp && !A.ko) { A.hp += atk.gainHp; A.max += atk.gainHp; st.ev.push({ k: 'heal', side: X, i: PX.active, v: atk.gainHp }); L(st, `${cname(A.id)} y prend du plaisir : +${atk.gainHp} PV.`, 'fx'); }
    if (atk.nextHp && !A.ko) { const had = PX.nextHp; PX.nextHp = atk.nextHp; L(st, had ? `${cname(A.id)} renvoie un MP de soutien (toujours +${PX.nextHp} PV, ce n'est pas cumulable).` : `${cname(A.id)} envoie un MP de soutien (+${PX.nextHp} PV au prochain équipier envoyé).`, 'fx'); }
    if ((atk.tags || []).includes('coom') && !A.ko && !A.gone && A.id !== 'isssoufle_ex' && aliveIn(PX, 'isssoufle_ex') && !blocked(st, X)) koFighter(st, X, PX.team.indexOf(A), 'nnn');
    if (atk.selfKo && !A.ko) { L(st, `${cname(A.id)} quitte la partie, rageux.`); hurt(st, X, PX.team.indexOf(A), A.hp, 'self'); }
    if (atk.self && !A.ko) { L(st, `${cname(A.id)} perd ${atk.self} PV.`); hurt(st, X, PX.team.indexOf(A), atk.self, 'self'); }
