      if (atk.self) v -= atk.self >= A.hp ? (D && dmg >= D.hp && PY.team.filter((f) => !f.ko && !f.gone).length === 1 ? -100 : 200) : atk.self * 0.6;
      if (atk.charge && !A.charging) v = 45;
      if (atk.heal) v = A.max - A.hp >= 25 ? 35 : 5;
      if (atk.mark && !A.marks[atk.mark]) v = 30;
