  refreshFab();
  scan();
  let scanT;
  new MutationObserver((muts) => {
    if (muts.some((m) => [...m.addedNodes].some((n) => n.nodeType === 1 && !n.closest('.bb-ov, .bb-fab, .bb-toast')))) {
      clearTimeout(scanT); scanT = setTimeout(scan, 400);
    }
  }).observe(document.body, { childList: true, subtree: true });
  window.addEventListener('focus', refreshFab);   // synchro entre onglets

  if (NET.enabled()) NET.start();   // visible dans le salon des duels et prêt à recevoir des défis
