  setTimeout(() => { const s = load(); if (dailyReady(s) && GM_getValue('bb_daily_toast', '') !== todayKey()) { GM_setValue('bb_daily_toast', todayKey()); toast(`🎁 Ton booster quotidien (${KINDS.daily.n} cartes) t'attend !`, true); } }, 1500);
  GM_registerMenuCommand('Démo : simuler un booster quotidien', () => { openWin('shop'); setTimeout(() => startOpening(true, 'daily'), 250); });
  GM_registerMenuCommand('Démo : simuler un giga booster', () => { openWin('shop'); setTimeout(() => startOpening(true, 'giga'), 250); });

